#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package Yarp.ReverseProxy@2.0.0 #:package Polly@8.0.0 #:package Microsoft.Extensions.Caching.StackExchangeRedis@8.0.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable #:property PublishAot=true  using System.Threading.Channels; using Polly;  [SkipLocalsInit] public sealed class CircuitBreakerMiddleware {     private readonly Channel<ProxyRequest> _requestChannel;     private readonly AsyncCircuitBreakerPolicy _circuitBreaker;     private readonly IMemoryCache _cache;     private readonly CancellationTokenSource _cts;      public CircuitBreakerMiddleware(IMemoryCache cache)     {         _cache = cache;         _cts = new CancellationTokenSource();                  _requestChannel = Channel.CreateBounded<ProxyRequest>(             new BoundedChannelOptions(10_000)             {                 SingleReader = true,                 AllowSynchronousContinuations = true,                 FullMode = BoundedChannelFullMode.DropOldest             });                  _circuitBreaker = Policy             .Handle<HttpRequestException>()             .CircuitBreakerAsync(                 exceptionsAllowedBeforeBreaking: 5,                 durationOfBreak: TimeSpan.FromSeconds(30));                  _ = Task.Run(ProcessRequestsAsync);     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public async Task<ProxyResponse> ExecuteAsync(ProxyRequest request)     {         await _requestChannel.Writer.WriteAsync(request, _cts.Token);         return await request.Completion.Task;     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     private async Task ProcessRequestsAsync()     {         await foreach (var request in _requestChannel.Reader.ReadAllAsync(_cts.Token))         {             var response = await _circuitBreaker.ExecuteAsync(() =>                  ProcessRequestWithBreakerAsync(request));             request.Completion.SetResult(response);         }     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     private async Task<ProxyResponse> ProcessRequestWithBreakerAsync(ProxyRequest request)     {         using var buffer = MemoryPool<byte>.Shared.Rent(4096);         var memory = buffer.Memory;                  // 实现基于TokenRing的熔断处理         var response = new ProxyResponse();         // ... 实际熔断逻辑实现                  return response;     } }  var builder = WebApplication.CreateBuilder(args);  // Redis缓存配置 builder.Services.AddStackExchangeRedisCache(options => {     options.Configuration = "localhost";     options.InstanceName = "YarpCircuitBreaker_"; });  // 熔断中间件 builder.Services.AddSingleton<CircuitBreakerMiddleware>();  // YARP配置 builder.Services.AddReverseProxy()     .AddTransforms(context =>     {         // 请求转换         context.AddRequestTransform(async transformContext =>         {             var cacheKey = transformContext.ProxyRequest.RequestUri.ToString();             if (builder.Services.GetRequiredService<IMemoryCache>().TryGetValue(cacheKey, out var cachedResponse))             {                 transformContext.ProxyResponse = (ProxyResponse)cachedResponse;                 return;             }                          // 添加自定义请求头             transformContext.ProxyRequest.Headers.Add("X-Forwarded-Time", DateTime.UtcNow.ToString("o"));         });                  // 响应转换         context.AddResponseTransform(async transformContext =>         {             if (transformContext.ProxyResponse.IsSuccessStatusCode)             {                 var cacheKey = transformContext.ProxyRequest.RequestUri.ToString();                 builder.Services.GetRequiredService<IMemoryCache>().Set(                     cacheKey,                      transformContext.ProxyResponse,                     TimeSpan.FromMinutes(5));             }         });     });  var app = builder.Build();  app.MapReverseProxy();  app.Run();
